<script setup lang="ts">
import{nextTick,ref,useId}from'vue';import MTag from '../MTag.vue';import MValueBridge from './MValueBridge.vue';import type{MInputTagProps}from'./types';import{useReferenceConfig}from'./locale';
import{useDraftReset}from'./shared';
const props=withDefaults(defineProps<MInputTagProps>(),{max:Infinity,allowDuplicates:false,separator:','});const emit=defineEmits<{ 'update:modelValue':[value:string[]] }>();const{t}=useReferenceConfig();const identity=`ui-input-tag-${useId()}`,root=ref<HTMLElement>(),input=ref<HTMLInputElement>(),draft=ref(''),error=ref(''),composing=ref(false);
function add(values=[draft.value]){if(props.disabled||props.readonly||composing.value)return;const incoming=values.map(value=>value.trim()).filter(Boolean);if(!incoming.length)return;let next=[...props.modelValue];for(const value of incoming){if(!props.allowDuplicates&&next.includes(value)){error.value=t('tag.duplicate','标签不能重复。');return;}next.push(value);}if(next.length>props.max){error.value=t('tag.max','标签数量已达上限。');return;}error.value='';emit('update:modelValue',next);void nextTick(()=>{if(props.modelValue.length===next.length&&next.every((value,index)=>props.modelValue[index]===value))draft.value='';});}
function remove(index:number){if(props.disabled||props.readonly)return;emit('update:modelValue',props.modelValue.filter((_,position)=>position!==index));void nextTick(()=>input.value?.focus());}
function key(event:KeyboardEvent){if(event.isComposing||composing.value||event.keyCode===229)return;if(event.key==='Enter'||event.key===props.separator){event.preventDefault();add();}else if(event.key==='Backspace'&&!draft.value&&props.modelValue.length){event.preventDefault();remove(props.modelValue.length-1);}}
function paste(event:ClipboardEvent){if(props.disabled||props.readonly)return;const text=event.clipboardData?.getData('text')||'';if(text.includes(props.separator)||text.includes('\n')){event.preventDefault();add(text.split(props.separator).flatMap(value=>value.split(/\r?\n/)));}}
useDraftReset(root,()=>{composing.value=false;draft.value='';error.value='';if(input.value)input.value.value='';});
</script>
<template><div ref="root" class="ui-ri"><label class="ui-ri__label" :for="id||identity">{{label}}</label><div class="ui-ri__row"><MTag v-for="(tag,index) in modelValue" :key="index" :closable="!readonly" :disabled="disabled" :close-label="t('tag.remove','移除标签')+tag" @close="remove(index)">{{tag}}</MTag></div><div class="ui-ri__row"><input :id="id||identity" ref="input" v-model="draft" class="ui-ri__control" :disabled="disabled" :readonly="readonly" :aria-invalid="!!error||undefined" @compositionstart="composing=true" @compositionend="composing=false" @keydown="key" @paste="paste"><button type="button" class="ui-ri__button" :disabled="disabled||readonly||!draft.trim()" @click="add()">{{t('tag.add','添加')}}</button></div><p v-if="error" class="ui-ri__error" role="alert">{{error}}</p><MValueBridge v-bind="props" :values="modelValue" :error="modelValue.length>max?t('tag.max','标签数量超出上限。'):''"/></div></template>
